package org.circus.core;

import java.io.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;

/** Targeted original-command and progress/save regressions; no game assets required. */
public final class Dc3rHostTests {
    private static int checks;
    private static void check(boolean value,String name){checks++;if(!value)throw new AssertionError(name);}
    private static CircusScrVm.Value[] args(Object... values){CircusScrVm.Value[] a=new CircusScrVm.Value[values.length];for(int i=0;i<a.length;i++)a[i]=values[i] instanceof String?new CircusScrVm.Value((String)values[i]):new CircusScrVm.Value((Integer)values[i]);return a;}
    private static CircusScrVm vm(Dc3rHost host)throws IOException{ByteBuffer b=ByteBuffer.allocate(12+4+8+16+1).order(ByteOrder.LITTLE_ENDIAN);b.put("CircusScr1.0".getBytes(StandardCharsets.US_ASCII));b.putInt(1).putInt(23).putInt(0);for(int i=0;i<4;i++)b.putInt(0);b.put((byte)0);return new CircusScrVm(name->new CircusScrScript(name,b.array()),host,"unit");}
    private static byte[] save(Dc3rHost h)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();h.save(new DataOutputStream(b));return b.toByteArray();}
    public static void main(String[] ignored)throws Exception{System.out.println("PASS DC3R host "+run()+" checks");}
    public static int run()throws Exception{checks=0;
        Dc3rHost h=new Dc3rHost();CircusScrVm vm=vm(h);h.configureCatalogues("4\tev01\n","9\tunit\n");h.command(5,args("bg","ev01"),vm);check(h.readFlag((97<<16)+4)==1,"viewed CG writes original flag");h.command(148,args("next"),vm);check(h.readFlag((98<<16)+9)==1,"completed scenario writes original flag");
        h.writeFlag(5,123);h.writeFlag((99<<16)+7,18);byte[] older=save(h);h.writeFlag(5,999);h.writeFlag((99<<16)+7,26);h.writeFlag((97<<16)+5,1);h.load(new DataInputStream(new ByteArrayInputStream(older)));check(h.readFlag(5)==123,"save restores local variables");check(h.readFlag((99<<16)+7)==26,"save preserves current settings");check(h.readFlag((97<<16)+5)==1,"older save cannot relock CG");
        h.command(60,args("face_base","face_diff","",2),vm);check(h.layers[12].tint==0,"CsData(string).Val is zero in original Face handler");
        h.command(167,args(0,600,2),vm);check(vm.remainingMillis()==5000,"trscroll original timing uses second argument");h.elapse(2500,vm);check(h.layers[0].y==-300,"background scroll halfway");h.elapse(2500,vm);check(h.layers[0].y==-600,"background scroll endpoint");
        h.command(183,args("atlas"),vm);h.command(125,args(0,0,"work1",0,0,24,24),vm);h.command(127,args(256,8,24,5),vm);h.elapse(250,vm);check(h.animated(h.fore.quads.get(0)).sx==24,"original 34Hz pattern timing");
        Dc3rAnimation anim=new Dc3rAnimation("T1.16:X700.300@5w15:Y400:W300:H300");check(Math.abs(anim.durationSeconds-(400/5.0/12+15/12.0))<1e-9,"action duration includes trailing wait");check(Math.abs(anim.value('X',1,0)-640)<1e-9,"action speed samples position");check(anim.value('W',10,0)==300,"action static scale");
        h.command(44,args(),vm);h.command(155,args(),vm);h.command(153,args(4,3),vm);h.command(81,args(6,0),vm);check(h.menu.buttons.size()==8,"save page disables auto/recent slots");check(h.menu.buttons.get(0).left==248&&h.menu.buttons.get(0).top==262,"save cells preserve original coordinates");check(h.menu.buttons.get(0).targetFlag==(101<<16)+102&&h.menu.buttons.get(0).flagValue==0,"save cells bind selected slot");
        h.command(44,args(),vm);h.writeFlag((101<<16)+101,0);h.availableSaves.put(0,new Dc3rHost.SaveInfo("2026/10/29","sample"));h.command(81,args(6,1),vm);check(h.menu.buttons.size()==2,"load exposes saved slot and recent alias only");
        byte[] state=save(h);h.load(new DataInputStream(new ByteArrayInputStream(state)));check(h.menu.buttons.get(0).targetFlag==(101<<16)+102,"menu target binding survives save");check(h.works.get("work1").equals("system/atlas"),"work binding survives save");
        h.command(169,args("line"),vm);check(h.audio[5].equals("voice/unit/line"),"voice lookup includes script directory");h.command(169,args("000silent24"),vm);check(!h.audioActive[5],"silent voice placeholder does not request an asset");h.command(169,args("000silent24.pcm"),vm);check(!h.audioActive[5],"option silence placeholder accepts original pcm extension");
        h.command(44,args(),vm);h.command(97,args(100,100,300,150,"refresh"),vm);h.command(99,args(110,290,31,(99<<16)+7),vm);h.command(105,args(100,100,"work1",0,0,200,50),vm);h.command(105,args(110,105,"work1",0,0,180,40),vm);h.command(175,args(),vm);check(h.drag(200,120,true,vm),"original option slider accepts drag");check(h.readFlag((99<<16)+7)==15,"slider uses original steps minus one");check(h.buttonQuads(h.menu.buttons.get(0),0).get(0).width==90,"slider fill visible at half width without press");h.cancelDrag();
        h.command(44,args(),vm);h.command(5,args("bg","scene"),vm);h.command(121,args("name","first"),vm);h.command(121,args("name","second"),vm);check(h.canRewindHistory(0),"text creates bounded standalone rollback state");h.writeFlag((97<<16)+88,1);h.rewindHistory(0,vm);check(h.body.equals("first")&&h.history.size()==1&&vm.status()==CircusScrVm.Status.WAIT_CLICK,"history jump restores dialogue and VM wait");check(h.readFlag((97<<16)+88)==1,"history jump preserves newer CG progress");
        h.command(81,args(7,1),vm);check(h.backlogActive&&h.menuWaiting&&h.menu.buttons.stream().anyMatch(b->b.action.equals(":endlog")),"original backlog builds native layout and controls");h.cancel(vm);check(!h.backlogActive&&vm.status()==CircusScrVm.Status.RUNNING,"backlog cancel resumes LOG return script");
        check(h.command(81,args(100,0),vm),"original unhandled GAME mode only logs and returns");
        h.command(144,args(2),vm);check(vm.remainingMillis()==225&&!h.fore.quads.isEmpty(),"two original white flashes schedule 225ms");h.elapse(75,vm);check(h.fore.quads.isEmpty(),"white flash clears put at off phase");h.elapse(75,vm);check(!h.fore.quads.isEmpty(),"white flash repeats on phase");h.elapse(75,vm);check(h.fore.quads.isEmpty(),"white flash ends clear");
        h.command(182,args(1),vm);check(h.transitionMask.equals("system/maskltr"),"wipe selects original mask");h.command(62,args(),vm);check(h.transitionMask.isEmpty(),"ordinary fade clears prior wipe mask");
        h.command(81,args(210,0),vm);check(h.fore.quads.size()==25&&h.readFlag((5<<16)+1)==0&&vm.remainingMillis()==239000,"grand ending preserves original 25 panels and duration");h.elapse(239000,vm);check(h.readFlag((5<<16)+1)==1&&h.fore.quads.isEmpty(),"grand ending releases skip lock and pictures");
        h.command(155,args(),vm);h.command(156,args(20,30,295,36),vm);h.command(157,args(0,"work1",0,0,1,1,"mplay"),vm);h.command(158,args(0,0,0,"Track"),vm);h.textAssets=name->"bgm001\n";h.command(81,args(12,0),vm);check(h.menu.buttons.get(h.menu.buttons.size()-1).action.equals("mplay"),"music gallery uses original script slot and title");h.command(81,args(11,1),vm);check(h.audio[0].equals("bgm/bgm001"),"music gallery resolves original bgmlist");h.command(81,args(11,2),vm);
        h.command(129,args(),vm);h.command(164,args(0,0,28,0,400),vm);h.command(121,args("","Sample"),vm);h.command(127,args(4364,1,0,9999),vm);Dc3rHost.Text sample=h.fore.texts.get(0);check(sample.loopTyping&&h.displayText(sample,sample.text).isEmpty(),"option text animation targets CString rather than stale quad");h.elapse(100,vm);check(h.displayText(sample,sample.text).equals("Sample"),"option sample follows native character speed");
        h.command(5,args("bg","moving"),vm);h.command(10,args(500,440,248),vm);h.elapse(1000,vm);int storyX=h.layers[0].x;h.command(37,args("advmenu"),vm);h.command(5,args("system","option_back"),vm);h.elapse(1000,vm);check(h.layers[0].x==0&&h.layers[0].y==0&&h.layers[0].moveTime==0,"new background cancels prior story scroll");h.command(122,args(),vm);h.elapse(1000,vm);check(h.layers[0].x==storyX&&h.layers[0].moveTime==0,"PrevBack freezes copied story background in menu");h.command(38,args(),vm);check(h.layers[0].moveTime>0&&h.layers[0].x==storyX,"return restores original pending story scroll");
        check(!h.command(200,args(),vm),"unverified function does not silently succeed");
        return checks;
    }
}
